INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Peppol 5-corner ("Digital Postman")', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Slovakia''s national CIUS, API specifications, and Ministry of Finance regulations are still being finalised — confirm current requirements directly with the Financial Directorate before building an integration.', 'Slovakia has been here before — a voluntary B2B framework was planned for 2022 and quietly shelved. This time the mandate is legislated with a firm date.', 'Slovakia hasn''t published a national CIUS — it''s relying on the base EN 16931 standard rather than adding a distinctly Slovak layer on top.', 'The "5-corner" label matters here: Digital Postmen don''t just move invoices between trading partners, they report the data to the tax authority in the same step.', 'The 2026 voluntary phase exists specifically so businesses can iron out integration problems before the mandate has teeth.', 'Slovakia is explicitly taking an educational approach through the first half of 2027 — but the fines behind that grace period are real.' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'EN 16931', 'UBL 2.1 / CII syntax');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Slovakia';
