INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Syntax & standard', '[["Standard", "EN 16931"], ["Accepted syntaxes", "UBL 2.1 or UN/CEFACT CII"], ["National CIUS", "Not yet implemented — under evaluation"]]', 'Unlike Romania''s RO_CIUS or Croatia''s HR-FISK, Slovakia is currently building on the plain European base standard — watch for a national CIUS to be defined as the rollout matures.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers', '[["Peppol scheme", "0245 — SG:DIC"], ["Identifier", "10-digit Slovak Tax ID (DIČ)"], ["Issued by", "Financial Administration of the Slovak Republic"]]', 'Use scheme 0245 when registering Slovak end users on the Peppol network — this is the identifier that resolves to a specific recipient''s DIČ for routing purposes.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s explicitly excluded', '[["PDFs / scanned images", "Not treated as e-invoices"], ["B2C transactions", "Out of scope"], ["Other exemptions", "Classified information; certain government bodies"]]', 'The FAQ document (9/DPH/2025) is explicit: an e-invoice is defined as a machine-readable structured XML file, full stop — nothing that merely looks like an invoice qualifies.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving & timing', '[["Retention", "10 years, original XML format"], ["Issuance deadline (until 2030)", "15 days from the tax point"], ["Issuance deadline (from 2030)", "Shortens to 10 days"]]', 'Sending the invoice through a Digital Postman within the deadline is what fulfils the issuance obligation — the clock is on transmission, not just generation.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The 5-corner model', '[["Corners 1–4", "Standard Peppol exchange (supplier → AP → AP → buyer)"], ["Corner 5", "Real-time reporting to the Financial Administration"], ["Service provider term", "\"Digitálni poštári\" (Digital Postmen)"]]', 'This is a genuine architectural step beyond Belgium''s or the UK''s plain 4-corner models — the reporting leg is built into the same transmission, not a separate filing.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'IS EFA vs. the B2B network', '[["IS EFA", "Central B2G/G2G platform, live since 2023"], ["B2B", "Peppol-based Digital Postman network, extending the same principles"]]', 'Don''t confuse the two — B2G invoices to IS EFA use UBL 2.1 or CII D16B directly; B2B invoices move via accredited Digital Postmen over Peppol, with IS eFaktúra receiving the reported data.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Validation & error handling', '[["Pre-send validation", "Digital Postman flags format/data errors before transmission"], ["Post-transmission correction", "Formal credit note + new corrected invoice"], ["Direct modification", "Not possible once transmitted"]]', 'Rejection by the recipient must be handled bilaterally between supplier and buyer — there''s no reject function within the Peppol network itself for this purpose.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Foreign companies (B2G context)', '[["Channel", "Email-based submission"], ["Confirmation", "Confirmed or rejected via email by the government"]]', 'This lighter-touch email path applies specifically to B2G scenarios for foreign entities — B2B still requires a Digital Postman relationship once the 2027 mandate applies.', NULL, NULL, NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Initial breach', 'Up to €10,000', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Repeated offences', 'Up to €100,000', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🎓 Educational approach through mid-2027', NULL, NULL, '2026 and the first half of 2027 serve as grace periods with an emphasis on education rather than punishment — though penalties can technically still apply post-go-live for egregious cases.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📖 Where to check the fine print', NULL, NULL, 'The Financial Directorate''s official FAQ ("Najčastejšie otázky a odpovede k eFaktúre", document 9/DPH/2025) and detailed technical standards (schemas, code lists, Peppol API specifications) are being issued via a generally binding regulation of the Ministry of Finance — check info-efaktura.sk and financnasprava.sk for updates.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔁 A mandate that''s been delayed before', NULL, NULL, 'Given the earlier 2022 voluntary framework was shelved, it''s worth treating the 2027 date with appropriate confidence but staying alert for any further schedule changes as the deadline approaches.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Assess your current invoicing systems', 'Check compatibility with EN 16931 / UBL XML output and identify any necessary upgrades before the mandatory go-live.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Select and contract an accredited Digital Postman', 'Do this well ahead of 1 January 2027 — and be aware that from 1 July 2027, only certified Digital Postmen may be used at all.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Use the 2026 voluntary phase to test end-to-end', 'Register voluntarily to pilot invoice submission, validation, and correction workflows before the mandate carries real consequences.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your Peppol participant ID uses scheme 0245', 'Make sure your 10-digit DIČ is correctly registered under the Slovak identifier scheme — this is what makes you routable on the network.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Train staff on the correction workflow', 'Since direct modification of a transmitted invoice isn''t possible, make sure your team understands the credit-note-plus-reissue process before they need it under pressure.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Slovakia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build the 15-day (soon 10-day) issuance deadline into your process', 'Automate submission close to the tax point rather than batching — the deadline runs from the chargeable event, not from when someone gets around to generating the file.');
